    // The walk re-runs the component the way a render does: top to bottom,
    // every line with code on it — dwelling where a history line lights up,
    // and each stays lit once lit.
    let at = FLIP_MS;
    for (const line of REPLAY_WALK) {
      schedule(() => {
        setActiveLine(line);
        lightNote(NOTE_INDEX[line]);
      }, at);
      at += NOTE_LINES.has(line) ? NOTE_MS : SWEEP_MS;
    }
    schedule(() => {
      setFlipped(false);
      setActiveLine(null);
      clearNotes();
    }, at);
    // One flip later the front is square to the reader again, and only then
    // does the face catch up with the state it has been holding: the number
    // changes in view, rather than behind a turning card where the reveal
    // would be spent on nobody. Both marks ride the same commit — the wash
    // comes from the remount (the number is keyed by this value) and the
    // rise from the class the fresh digits mount with.
    schedule(() => {
      setShown(next);
      setSettling(true);
