      // the half-second the card spends turning back would set a newer
      // count, and this reveal would then paint the older one over it.
      replayingRef.current = false;
    }, at + FLIP_MS);
  };

  return (
    <StateCardShell
      facts={[
        "setCount stores the value where React keeps it",
        "then React calls the component again",
      ]}
      pill="useState"
      title="state-card.tsx"
      tone="state"
    >
